mapped = {}
unmapped = []

for raw in raw_captions:
    lower_raw = raw.lower()
    if lower_raw in ALLOWED_LOWER:
        mapped[raw] = ALLOWED_LOWER[lower_raw]
        continue
    
    # Try fuzzy matching
    matches = difflib.get_close_matches(lower_raw, ALLOWED_LOWER.keys(), n=1, cutoff=0.7)
    if matches:
        mapped[raw] = ALLOWED_LOWER[matches[0]]
    else:
        # custom hardcoded fixes
        if 'trimming' in lower_raw and 'shaping' in lower_raw: mapped[raw] = 'Trimming and Shaping'
        elif 'trimming' in lower_raw: mapped[raw] = 'Trimming Activity'
        elif 'cleaning' in lower_raw and 'dry leaves' in lower_raw: mapped[raw] = 'Cleaning and Removal of Fallen Dry Leaves'
        elif 'pruning' in lower_raw: mapped[raw] = 'Pruning'
        elif 'weeding' in lower_raw or 'weedding' in lower_raw: mapped[raw] = 'Weeding'
        elif 'washing' in lower_raw and 'plant' in lower_raw: mapped[raw] = 'Washing of Plants'
        elif 'npk' in lower_raw: mapped[raw] = 'Application of NPK'
        elif 'micro nutrient' in lower_raw: mapped[raw] = 'Application of Micro Nutrients'
        elif 'manual water' in lower_raw: mapped[raw] = 'Manual Watering'
        elif 'dusting' in lower_raw: mapped[raw] = 'Dusting of Plants'
        elif 'soil' in lower_raw and 'cultivation' in lower_raw: mapped[raw] = 'Soil Cultivation'
        elif 'pesticide' in lower_raw: mapped[raw] = 'Application of Pesticides'
        elif 'grass clipping' in lower_raw: mapped[raw] = 'Removal of Grass Clippings / Cleaning After Lawn Mowing'
        elif 'dry leaves' in lower_raw and 'removal' in lower_raw: mapped[raw] = 'Removal of Dry Leaves'
        elif 'weeds' in lower_raw and 'removal' in lower_raw: mapped[raw] = 'Removal of Weeds'
        elif 'compost' in lower_raw: mapped[raw] = 'Application of Compost'
        else:
            unmapped.append(raw)

print(f"Mapped {len(mapped)} captions. Unmapped {len(unmapped)} captions.")
if unmapped:
    print("Unmapped:", unmapped[:20])

with open("mapping.json", "w", encoding="utf-8") as f:
    json.dump(mapped, f, indent=2)
